INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63498650', 63498650, 'analyze_legacy', 'Kab. Pasuruan', 'kabkota', 'DINAS PERHUBUNGAN', 'Jasa Konsultansi Pengawasan Pengadaan dan Pemasangan CCTV danTiang Monopole', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Timur, Pasuruan (Kab.)', 9300000, 'February 2026', 'APBD', 1, 1, '1 Paket', 'Persiapan Review dokumen kontrak, spesifikasi teknis, dan gambar kerja. Koordinasi dengan pihak pengguna jasa dan kontraktor pelaksana. Pengawasan Teknis Mengawasi proses pengadaan material CCTV dan tiang monopole agar sesuai spesifikasi. Memastikan pemasangan CCTV (indoor/outdoor) sesuai standar kualitas gambar, jaringan, dan keamanan. Mengawasi pemasangan tiang monopole (pondasi, struktur, ketinggian, keamanan konstruksi). Memastikan integrasi CCTV dengan sistem monitoring (server, jaringan, penyimpanan data). Pengendalian Mutu & Waktu Melakukan inspeksi berkala terhadap material dan pekerjaan. Memberikan instruksi teknis bila terjadi deviasi dari spesifikasi. Memastikan pekerjaan selesai sesuai jadwal yang ditetapkan. Pelaporan Menyusun laporan harian/mingguan/bulanan terkait progres pekerjaan. Memberikan rekomendasi teknis atas permasalahan yang muncul. Menyusun laporan akhir pengawasan.', 'Laporan ini dibuat sebanyak 1 (Satu) buku laporan asli dan 1 (satu) Copy di kertas A4 merupakan hasil dari pengawasan yang berisi : a. Berita Acara sehubungan dengan penyelesaian pekerjaan di lapangan, serta untuk keperluan pembayaran angsuran. b. daftar volume dan nilai pekerjaan serta penambahan atau pengurangan pekerjaan guna keperluan pembayaran. c. laporan harian, mingguan dan bulanan Berita Acara kemajuan pekerjaan penyerahan pertama dan kedua serta formulir-formulir lainnya yang diperlukan untuk kebutuhan dokumen pembangunan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 954487);
